using System;using System.Collections.Generic;using System.Linq;using SpatialWallpaper.Sdk.Execution;
namespace SpatialWallpaper.Sdk.Native {
 public enum NativeUploadPhase {Receiving=1,Queued=2,Preparing=3,Uploading=4,WaitingGpu=5,Ready=6,Published=7,Canceled=8,Retired=9,Failed=10}
 public sealed class NativeUploadSpec {
  public readonly string Kind;public readonly int Width,Height,Vertices,Indices,Bytes;public readonly IReadOnlyList<int> SubmeshIndices;
  NativeUploadSpec(string kind,int width,int height,int vertices,int indices,int bytes,int[] submeshes=null){SubmeshIndices=submeshes==null?null:Array.AsReadOnly((int[])submeshes.Clone());Kind=kind;Width=width;Height=height;Vertices=vertices;Indices=indices;Bytes=bytes;}
  public static NativeUploadSpec Mesh(int vertices,params int[] submeshIndices){if(vertices<3||vertices>8192||submeshIndices==null||submeshIndices.Length<1||submeshIndices.Length>64||submeshIndices.Any(n=>n<3||n>196608||n%3!=0))throw new ArgumentOutOfRangeException("dynamic-mesh-shape");int indices=checked(submeshIndices.Sum());int bytes=checked(vertices*72+indices*4);if(bytes>1048576)throw new ArgumentOutOfRangeException("dynamic-upload-size");return new NativeUploadSpec("mesh",0,0,vertices,indices,bytes,submeshIndices);}
  public static NativeUploadSpec Texture(int width,int height){if(width<1||height<1||width>512||height>512)throw new ArgumentOutOfRangeException("dynamic-texture-shape");return new NativeUploadSpec("texture",width,height,0,0,checked(width*height*4));}
 }
 public sealed class NativeUploadInbox:IDisposable {
  public const int ChunkLimit=65536,PendingLimit=4;
  internal sealed class Work {internal long Id,Epoch;internal NativeUploadSpec Spec;internal byte[] Bytes;internal ResourceLease Staging;internal int Received;internal NativeUploadPhase Phase;internal float[] Bounds;}
  readonly object gate=new object();readonly Guid session;readonly uint generation;readonly ResourceLedger ledger;readonly Dictionary<long,Work> work=new Dictionary<long,Work>();long next,epoch;bool disposed;
  public NativeUploadInbox(Guid session,uint generation,long epoch,ResourceLedger ledger){if(session==Guid.Empty||generation<1||epoch<1)throw new ArgumentException("dynamic-upload-owner");this.session=session;this.generation=generation;this.epoch=epoch;this.ledger=ledger??throw new ArgumentNullException(nameof(ledger));}
  public long AuthorityEpoch{get{lock(gate)return epoch;}}
  void Live(Guid s,uint g,long e){if(disposed||s!=session||g!=generation||e!=epoch)throw new InvalidOperationException("dynamic-upload-owner-generation-or-authority");}
  Work Get(long id,long e){if(disposed||e!=epoch||!work.TryGetValue(id,out var w)||w.Epoch!=e)throw new InvalidOperationException("dynamic-upload-stale-token");return w;}
  public long Begin(Guid session,uint generation,long epoch,NativeUploadSpec spec){lock(gate){Live(session,generation,epoch);if(spec==null||work.Count>=64||work.Values.Count(w=>w.Phase<NativeUploadPhase.Canceled)>=PendingLimit)throw new InvalidOperationException("dynamic-upload-pending-limit");var staging=ledger.Reserve(new ResourceCost(checked(1024L+spec.Bytes),0,0,0));try{var bytes=new byte[spec.Bytes];var value=new Work{Id=checked(++next),Epoch=epoch,Spec=spec,Bytes=bytes,Staging=staging,Phase=NativeUploadPhase.Receiving};work.Add(value.Id,value);staging.Commit();return value.Id;}catch{staging.Dispose();throw;}}}
  public void Append(long id,long epoch,int offset,byte[] chunk){lock(gate){var w=Get(id,epoch);if(w.Phase!=NativeUploadPhase.Receiving||chunk==null||chunk.Length<1||chunk.Length>ChunkLimit||offset!=w.Received||chunk.Length>w.Spec.Bytes-offset)throw new InvalidOperationException("dynamic-upload-chunk-order-size-or-state");Buffer.BlockCopy(chunk,0,w.Bytes,offset,chunk.Length);w.Received+=chunk.Length;}}
  public void Seal(long id,long epoch){lock(gate){var w=Get(id,epoch);if(w.Phase!=NativeUploadPhase.Receiving||w.Received!=w.Spec.Bytes)throw new InvalidOperationException("dynamic-upload-incomplete");if(w.Spec.Kind=="mesh"){float minX=float.MaxValue,minY=minX,minZ=minX,maxX=float.MinValue,maxY=maxX,maxZ=maxX;for(int i=0;i<w.Spec.Vertices;i++){float x=BitConverter.ToSingle(w.Bytes,i*72),y=BitConverter.ToSingle(w.Bytes,i*12+4),z=BitConverter.ToSingle(w.Bytes,i*12+8);if(float.IsNaN(x)||float.IsNaN(y)||float.IsNaN(z)||float.IsInfinity(x)||float.IsInfinity(y)||float.IsInfinity(z)||Math.Abs(x)>1000000||Math.Abs(y)>1000000||Math.Abs(z)>1000000)throw new InvalidOperationException("dynamic-mesh-nonfinite-or-bounds");minX=Math.Min(minX,x);minY=Math.Min(minY,y);minZ=Math.Min(minZ,z);maxX=Math.Max(maxX,x);maxY=Math.Max(maxY,y);maxZ=Math.Max(maxZ,z);}for(int i=0;i<w.Spec.Indices;i++)if(BitConverter.ToUInt32(w.Bytes,w.Spec.Vertices*72+i*4)>=w.Spec.Vertices)throw new InvalidOperationException("dynamic-mesh-index-range");for(int i=0;i<w.Spec.Vertices*18;i++){float channel=BitConverter.ToSingle(w.Bytes,i*4);if(float.IsNaN(channel)||float.IsInfinity(channel))throw new InvalidOperationException("dynamic-mesh-channel-nonfinite");}w.Bounds=new[]{minX,minY,minZ,maxX,maxY,maxZ};}w.Phase=NativeUploadPhase.Queued;}}
  public NativeUploadPhase State(long id){lock(gate){if(!work.TryGetValue(id,out var w))throw new InvalidOperationException("dynamic-upload-token");return w.Phase;}}
  internal Work TakeReady(){lock(gate){if(disposed)return null;var w=work.Values.FirstOrDefault(x=>x.Phase==NativeUploadPhase.Queued);if(w!=null)w.Phase=NativeUploadPhase.Preparing;return w;}}
  internal bool Current(Work w){lock(gate)return !disposed&&w.Epoch==epoch&&w.Phase<NativeUploadPhase.Canceled;}
  internal bool Transition(Work w,NativeUploadPhase phase){lock(gate){if(!Current(w))return false;w.Phase=phase;return true;}}
  internal void ReleaseStaging(Work w){lock(gate){w.Bytes=null;w.Bounds=null;w.Staging?.Dispose();w.Staging=null;}}
  public void Cancel(long id,long epoch){lock(gate){var w=Get(id,epoch);if(w.Phase==NativeUploadPhase.Published)throw new InvalidOperationException("dynamic-upload-published-requires-retirement");w.Phase=NativeUploadPhase.Canceled;}}
  public void Revoke(long newEpoch){lock(gate){if(disposed||newEpoch<=epoch)throw new InvalidOperationException("dynamic-upload-revoke-order");epoch=newEpoch;foreach(var w in work.Values)if(w.Phase!=NativeUploadPhase.Published&&w.Phase<NativeUploadPhase.Canceled)w.Phase=NativeUploadPhase.Canceled;}}
  internal void Publish(Work w,Action action){lock(gate){if(!Current(w)||w.Phase!=NativeUploadPhase.Ready)throw new InvalidOperationException("dynamic-upload-not-ready-or-authorized");action();w.Phase=NativeUploadPhase.Published;}}
  internal void Forget(Work w){lock(gate){ReleaseStaging(w);work.Remove(w.Id);}}
  internal Work[] All(){lock(gate)return work.Values.ToArray();}
  public void Dispose(){lock(gate){if(disposed)return;disposed=true;foreach(var w in work.Values){if(w.Phase!=NativeUploadPhase.Published)w.Phase=NativeUploadPhase.Canceled;}}}
 }
}
